/**
 * The source text of the skill Lambda's `page-style.js`: the hub's standalone
 * page stylesheet plus the brand mark, as constants. Kept here, beside
 * `app-page-shell.ts`, so there is ONE place the look lives and a spec holds the
 * Lambda's copy to it (`scripts/gen-alexa-lambda-page-style.ts` writes it).
 */
import { APP_PAGE_LOGOS, APP_PAGE_STYLE } from './app-page-shell.js'

export function alexaLambdaPageStyleSource(): string {
  return `// biome-ignore-all format: generated file
// biome-ignore-all lint: generated file
/**
 * GENERATED by scripts/gen-alexa-lambda-page-style.ts from the hub's page shell
 * (server/backend/src/auth/app-page-shell.ts). Do not edit: change the shell and
 * regenerate. The Lambda ships plain files, so the stylesheet travels as a constant.
 */
'use strict'

const STYLE = ${JSON.stringify(APP_PAGE_STYLE)}
const LOGO_DARK = ${JSON.stringify(APP_PAGE_LOGOS.dark)}
const LOGO_LIGHT = ${JSON.stringify(APP_PAGE_LOGOS.light)}

module.exports = { STYLE, LOGO_DARK, LOGO_LIGHT }
`
}
